theorem Array.isEqvAux_of_rel✝.{u_1} {α : Type u_1} {r : α → α → Bool} {xs ys : Array α}
  (hsz : xs.size = ys.size) {i : ℕ} (hi : i ≤ xs.size)
  (w : ∀ (j : ℕ) (hj : j < i), r xs[j] ys[j] = true) : xs.isEqvAux ys hsz r i hi = true

theorem Array.rel_of_isEqvAux✝.{u_1} {α : Type u_1} {r : α → α → Bool} {xs ys : Array α}
  (hsz : xs.size = ys.size) {i : ℕ} (hi : i ≤ xs.size) (heqv : xs.isEqvAux ys hsz r i hi = true)
  {j : ℕ} (hj : j < i) : r xs[j] ys[j] = true

theorem List.Pairwise.map.{u_1, u_2} {β : Type u_1} {α : Type u_2} {R : α → α → Prop} {l : List α}
  {S : β → β → Prop} (f : α → β) (H : ∀ (a b : α), R a b → S (f a) (f b)) (p : List.Pairwise R l) :
  List.Pairwise S (List.map f l)

theorem List.Pairwise.forall_of_forall_of_flip.{u_1} {α✝ : Type u_1} {l : List α✝} {R : α✝ → α✝ → Prop}
  (h₁ : ∀ x ∈ l, R x x) (h₂ : List.Pairwise R l) (h₃ : List.Pairwise (flip R) l) ⦃x : α✝⦄ :
  x ∈ l → ∀ ⦃y : α✝⦄, y ∈ l → R x y

theorem List.pairwise_and_iff.{u_1} {α✝ : Type u_1} {R : α✝ → α✝ → Prop} {l : List α✝}
  {S : α✝ → α✝ → Prop} :
  List.Pairwise (fun a b => R a b ∧ S a b) l ↔ List.Pairwise R l ∧ List.Pairwise S l

theorem List.Pairwise.imp₂.{u_1} {α✝ : Type u_1} {R S T : α✝ → α✝ → Prop} {l : List α✝}
  (H : ∀ (a b : α✝), R a b → S a b → T a b) (hR : List.Pairwise R l) (hS : List.Pairwise S l) :
  List.Pairwise T l

theorem List.Pairwise.of_map.{u_1, u_2} {β : Type u_1} {α : Type u_2} {R : α → α → Prop} {l : List α}
  {S : β → β → Prop} (f : α → β) (H : ∀ (a b : α), S (f a) (f b) → R a b)
  (p : List.Pairwise S (List.map f l)) : List.Pairwise R l

theorem List.eraseP_comm.{u_1} {α : Type u_1} {p q : α → Bool} {l : List α}
  (h : ∀ a ∈ l, ¬p a = true ∨ ¬q a = true) :
  List.eraseP q (List.eraseP p l) = List.eraseP p (List.eraseP q l)

theorem List.eraseIdx_append.{u_1} {α✝ : Type u_1} {l l' : List α✝} {k : ℕ} :
  (l ++ l').eraseIdx k =
    if k < l.length then l.eraseIdx k ++ l' else l ++ l'.eraseIdx (k - l.length)

theorem List.getElem_modifyHead.{u_1} {α : Type u_1} {l : List α} {f : α → α} {i : ℕ}
  (h : i < (List.modifyHead f l).length) :
  (List.modifyHead f l)[i] = if h' : i = 0 then f l[0] else l[i]

theorem List.insertIdx_eraseIdx.{u} {α : Type u} {a : α} {i : ℕ} {as : List α} {j : ℕ} (h : i < as.length) :
  (as.eraseIdx i).insertIdx j a =
    if i ≤ j then (as.insertIdx (j + 1) a).eraseIdx i else (as.insertIdx j a).eraseIdx (i + 1)

theorem List.getElem_insertIdx.{u} {α : Type u} {l : List α} {x : α} {i j : ℕ}
  (h : j < (l.insertIdx i x).length) :
  (l.insertIdx i x)[j] = if h₁ : j < i then l[j] else if h₂ : j = i then x else l[j - 1]

theorem List.findSomeM?_toArray.{u_1, u_2, u_3} {m : Type u_1 → Type u_2} {α : Type u_3} {β : Type u_1}
  [Monad m] [LawfulMonad m] (f : α → m (Option β)) (l : List α) :
  Array.findSomeM? f l.toArray = List.findSomeM? f l

theorem Array.isPrefixOfAux.eq_def✝.{u} {α : Type u} [BEq α] (as bs : Array α) (hle : as.size ≤ bs.size)
  (i : ℕ) :
  as.isPrefixOfAux bs hle i =
    if h : i < as.size then
      have a := as[i];
      have this := ⋯;
      have b := bs[i];
      if (a == b) = true then as.isPrefixOfAux bs hle (i + 1) else false
    else true

theorem Array.zipWithAll.go.eq_def✝.{u, u_1, u_2} {α : Type u} {β : Type u_1} {γ : Type u_2}
  (f : Option α → Option β → γ) (as : Array α) (bs : Array β) (i : ℕ) (cs : Array γ) :
  Array.zipWithAll.go✝ f as bs i cs =
    if i < max as.size bs.size then
      have a := as[i]?;
      have b := bs[i]?;
      Array.zipWithAll.go✝ f as bs (i + 1) (cs.push (f a b))
    else cs

theorem List.foldrM_toArray.{u_1, u_2, u_3} {m : Type u_1 → Type u_2} {α : Type u_3} {β : Type u_1}
  [Monad m] (f : α → β → m β) (init : β) (l : List α) :
  Array.foldrM f init l.toArray = List.foldrM f init l

theorem List.forIn'_toArray.{u_1, u_2, u_3} {m : Type u_1 → Type u_2} {α : Type u_3} {β : Type u_1}
  [Monad m] (l : List α) (b : β) (f : (a : α) → a ∈ l.toArray → β → m (ForInStep β)) :
  forIn' l.toArray b f = forIn' l b fun a m b => f a ⋯ b

theorem List.foldrM_toArray'.{u_1, u_2, u_3} {m : Type u_1 → Type u_2} {α : Type u_3} {β : Type u_1}
  {start : ℕ} [Monad m] (f : α → β → m β) (init : β) (l : List α) (h : start = l.toArray.size) :
  Array.foldrM f init l.toArray start = List.foldrM f init l

theorem List.zipWithAll_toArray.{u_1, u_2, u_3} {α : Type u_1} {β : Type u_2} {γ : Type u_3}
  (f : Option α → Option β → γ) (as : List α) (bs : List β) :
  Array.zipWithAll f as.toArray bs.toArray = (List.zipWithAll f as bs).toArray

def Array.erase.match_1.splitter✝.{u_1, u_2} {α : Type u_1} (as : Array α)
  (motive : Option (Fin as.size) → Sort u_2) (x✝ : Option (Fin as.size)) (h_1 : Unit → motive none)
  (h_2 : (i : Fin as.size) → motive (some i)) : motive x✝

theorem List.findFinIdx?_loop_toArray✝.{u_1} {α✝ : Type u_1} {l' : List α✝} {p : α✝ → Bool} {j : ℕ}
  {l : List α✝} {h : l'.length + j = l.length} (w : l' = List.drop j l) :
  Array.findFinIdx?.loop✝ p l.toArray j = List.findFinIdx?.go p l l' j h

theorem List.foldlM_toArray.{u_1, u_2, u_3} {m : Type u_1 → Type u_2} {β : Type u_1} {α : Type u_3}
  [Monad m] (f : β → α → m β) (init : β) (l : List α) :
  Array.foldlM f init l.toArray = List.foldlM f init l
